SettingsPanel: FC<SettingsPanelProps> = ({
  items,
  activeId,
  onSelect,
  sectionLabel,
  styles: settingsPanelStyles,
  className,
}) => {
  const headerId = useId();
  const rowRefs = useRef(new Map<string, HTMLButtonElement>());

  const {
    sectionLabelClassName = 'dial-h1-text',
    itemLabelClassName = 'dial-small-text',
    activeItemLabelClassName = 'dial-small-semi-text',
  } = settingsPanelStyles?.typography ?? {};
  const colors = settingsPanelStyles?.colors;
  const cssVars = buildCssVars({
    '--sp-section-label-text': colors?.sectionLabelText,
    '--sp-row-text': colors?.rowText,
    '--sp-row-bg-hover': colors?.rowBackgroundHover,
    '--sp-active-row-bg': colors?.activeRowBackground,
    '--sp-active-row-bg-hover': colors?.activeRowBackgroundHover,
    '--sp-active-row-text': colors?.activeRowText,
    '--sp-row-focus-outline': colors?.rowFocusOutline,
  });

  const activeIndex = items.findIndex((item) => item.id === activeId);

  const focusAndSelect = (index: number) => {
    if (index < 0 || index === activeIndex) return;
    const item = items[index];
    rowRefs.current.get(item.id)?.focus();
    onSelect(item.id);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        focusAndSelect(findEnabledIndex(items, activeIndex, 1));
        break;
      case 'ArrowUp':
        event.preventDefault();
        focusAndSelect(findEnabledIndex(items, activeIndex, -1));
        break;
      case 'Home':
        event.preventDefault();
        focusAndSelect(findFirstEnabledIndex(items));
        break;
      case 'End':
        event.preventDefault();
        focusAndSelect(findLastEnabledIndex(items));
        break;
      default:
        break;
    }
  };

  return (
    <div
      className={mergeClasses(
        'flex flex-col gap-3 bg-layer-raised',
        className,
        SETTINGS_PANEL_CLASS.panel,
      )}
      style={cssVars}
    >
      {sectionLabel && (
        <div className="flex h-16 shrink-0 items-center px-4">
          <span
            id={headerId}
            className={mergeClasses(styles.sectionLabel, sectionLabelClassName)}
          >
            {sectionLabel}
          </span>
        </div>
      )}
      <div
        role="tablist"
        aria-orientation="vertical"
        aria-labelledby={sectionLabel ? headerId : undefined}
        onKeyDown={handleKeyDown}
        // Roving tabindex lives on the tab buttons; the list itself is never
        // a tab stop, but jsx-a11y requires an interactive role to declare
        // its own (non-reachable) focusability.
        tabIndex={-1}
        className={mergeClasses(
          'flex flex-col gap-1 px-2',
          SETTINGS_PANEL_CLASS.tabList,
        )}
      >
        {items.map((item) => {
          const isActive = item.id === activeId;
          const isVisuallyActive = isActive && items.length > 1;
          return (
            <button
              key={item.id}
              ref={(element) => {
                if (element) rowRefs.current.set(item.id, element);
                else rowRefs.current.delete(item.id);
              }}
              type="button"
              role="tab"
              aria-selected={isActive}
              aria-disabled={item.disabled || undefined}
              disabled={item.disabled}
              tabIndex={isActive ? 0 : -1}
              onClick={() => {
                if (!item.disabled && !isActive) onSelect(item.id);
              }}
              className={mergeClasses(
                'flex h-11 w-full items-center gap-2 rounded-lg px-3 text-start desktop:h-10',
                'focus-visible:outline focus-visible:-outline-offset-1',
                styles.row,
                isVisuallyActive && styles.rowActive,
                SETTINGS_PANEL_CLASS.tab,
              )}
            >
              {item.icon}
              <span
                className={mergeClasses(
                  isVisuallyActive
                    ? activeItemLabelClassName
                    : itemLabelClassName,
                  !isVisuallyActive && 'text-primary',
                )}
              >
                {item.label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

export interface SettingsPanelItem {
  /** Stable identifier, matched against `SettingsPanelProps.activeId`. */
  id: string;
  /** Already-localized row label. */
  label: string;
  /** Row icon, rendered before the label. */
  icon?: ReactNode;
  /** Disabled rows cannot become active, render with a `not-allowed` cursor, and are skipped by keyboard navigation. Defaults to `false`. */
  disabled?: boolean;
}

export interface SettingsPanelProps {
  /** Rows to render, top to bottom. */
  items: SettingsPanelItem[];
  /** `id` of the currently selected item. */
  activeId: string;
  /** Fired with an item's `id` when the user selects an enabled row that is not already active. */
  onSelect: (id: string) => void;
  /** Already-localized header text rendered above the item list. Omit to render no header. */
  sectionLabel?: string;
  /** Style overrides. */
  styles?: SettingsPanelStyles;
  /** Additional CSS class applied to the root element. */
  className?: string;
}

export interface SettingsPanelStyles {
  /** Typography overrides. */
  typography?: SettingsPanelTypography;
  /** Color overrides applied as CSS custom properties. */
  colors?: SettingsPanelColors;
}

export interface SettingsPanelColors {
  /** Label color of the section header. Defaults to `--text-primary`. */
  sectionLabelText?: string;
  /** Label and icon color of an inactive row (enabled or disabled). Defaults to `--text-secondary`. */
  rowText?: string;
  /** Background color of an enabled, inactive row on hover. Defaults to `--bg-control-accent-alpha-hover`. */
  rowBackgroundHover?: string;
  /** Background color of the active row. Defaults to `--bg-control-accent-alpha`. */
  activeRowBackground?: string;
  /** Background color of the active row on hover. Defaults to `--bg-control-accent-alpha-hover`. */
  activeRowBackgroundHover?: string;
  /** Label and icon color of the active row. Defaults to `--text-accent`. */
  activeRowText?: string;
  /** Keyboard focus ring color. Defaults to `--stroke-focus-black`. */
  rowFocusOutline?: string;
}

export interface SettingsPanelTypography {
  /** Typography class applied to the section header. Defaults to `'dial-h1-text'`. */
  sectionLabelClassName?: string;
  /** Typography class applied to an inactive row's label. Defaults to `'dial-small-text'`. */
  itemLabelClassName?: string;
  /** Typography class applied to the active row's label. Defaults to `'dial-small-semi-text'`. */
  activeItemLabelClassName?: string;
}

SETTINGS_PANEL_CLASS = {
  /** The panel root, which carries the themed CSS variables. */
  panel: 'dial-settings-panel-panel',
  /** The vertical tab list holding the section rows. */
  tabList: 'dial-settings-panel-tab-list',
  /** Every section row, selected or not. */
  tab: 'dial-settings-panel-tab',
} as const

